/**
 * Messages, cut 6 (email in): what the bids@ reader (`gmail-sync`) does after a run that died copying a mail's files
 * (v2.6667). A worker that runs out of memory writes nothing on its way out: no `last_error`, no history point, no
 * label. So the next run read the same mail again and fetched the same file again, and the one after it, every minute.
 * On 2026-11-06 from 20:45Z a bid mail to bids@ (Gmail id 1a1b29b453e52e9b) did that for three and a
 * half hours, about 190 runs, each one fetching its large file as bids@, until Gmail's per-user download limit refused
 * every call as bids@ with *429 User-rate limit exceeded* from 00:21Z on 11-07.
 *
 * So before a run fetches a mail's files it writes down which mail it is on (`copyMarkWords`, kept in the row's
 * `last_error`, where Settings' health line already reads the last run's words). A run that ends well clears it, as it
 * always cleared `last_error`. A run that finds the words still there (`copyStop`) knows the run before it died on
 * that mail. It waits while that run might still be alive (`COPY_RUN_LIMIT_MS`, longer than any worker lives), then
 * takes the mail with its files left in Gmail, so the walk moves past it and nothing is fetched twice. Pure.
 */

/** The row's fields the guard reads: the last run's words and when they were written. */
export interface CopyStopState {
  last_error: string | null
  updated_at: string | null
}

/** How long a mark may be a run still at work: longer than a worker lives (400 s on the platform's paid plans). */
export const COPY_RUN_LIMIT_MS = 7 * 60_000

const MARK = /^Copying the files of mail ([A-Za-z0-9_-]+)\b/

/** The words a run writes before it fetches a mail's files. They stay on the row only when the run never finished. */
export function copyMarkWords(gmailId: string, bytes: number): string {
  const mb = Math.max(0.1, Math.round((Math.max(0, bytes) / (1024 * 1024)) * 10) / 10)
  return `Copying the files of mail ${gmailId} (${mb} MB) did not finish. The next run takes the mail and leaves its files in Gmail.`
}

/** The mail a mark names, or null when the words are not a mark. */
export function markedMail(words: string | null | undefined): string | null {
  return MARK.exec((words ?? '').trim())?.[1] ?? null
}

export type CopyStop =
  /** No mark: the run reads as before. */
  | { kind: 'none' }
  /** A mark young enough that its run may still be at work: this run leaves the box until then. */
  | { kind: 'wait'; gmailId: string; until: string }
  /** The run before died on this mail: take it with its files left in Gmail. */
  | { kind: 'bare'; gmailId: string }

/** What a run does about the last run's mark, from the row's words and their time. */
export function copyStop(state: CopyStopState | null | undefined, nowIso: string): CopyStop {
  const gmailId = markedMail(state?.last_error)
  if (!gmailId) return { kind: 'none' }
  const now = Date.parse(nowIso)
  const saved = Date.parse(state?.updated_at ?? '')
  if (Number.isFinite(now) && Number.isFinite(saved) && now < saved + COPY_RUN_LIMIT_MS) {
    return { kind: 'wait', gmailId, until: new Date(saved + COPY_RUN_LIMIT_MS).toISOString() }
  }
  return { kind: 'bare', gmailId }
}

/** A file row as the reader lists it: what `fetchBytes` reads. */
export interface FetchRow {
  kind: 'file' | 'link'
  keep?: 'copy' | 'tooBig'
  attachmentId?: string | null
  size?: number
}

/** How much of a mail the run fetches from Gmail to copy its files: the files kept by their attachment id. 0 fetches none. */
export function fetchBytes(rows: readonly FetchRow[]): { files: number; bytes: number } {
  let files = 0
  let bytes = 0
  for (const r of rows) {
    if (r.kind !== 'file' || r.keep !== 'copy' || !r.attachmentId) continue
    files++
    bytes += Math.max(0, r.size ?? 0)
  }
  return { files, bytes }
}

/**
 * The words a run saves when it stops with a mark still to act on: the mark first, then why this run stopped. So a
 * 429 that stops the run before it reached the marked mail keeps the mark, and the run after the hold still takes
 * that mail bare instead of fetching its files again.
 */
export function keepMark(mark: string | null, words: string): string {
  const own = markedMail(mark) && mark ? mark.trim() : ''
  if (!own) return words
  return markedMail(words) ? words : `${own} ${words}`
}

/** The mark itself out of the row's words, to carry through this run: the sentence pair `copyMarkWords` wrote. */
export function markOf(words: string | null | undefined): string | null {
  const w = (words ?? '').trim()
  if (!markedMail(w)) return null
  const end = w.indexOf('leaves its files in Gmail.')
  return end < 0 ? w : w.slice(0, end + 'leaves its files in Gmail.'.length)
}
